"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3344],{92772:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Binds every tagged ScreenGui in the local `PlayerGui`, now and as they\\nappear, and rescales on viewport changes. Later calls are no-ops.","params":[],"returns":[],"function_type":"static","source":{"line":138,"path":"src/ReplicatedStorage/SharedModules/Gui/ResponsiveScale.luau"}}],"properties":[],"types":[],"name":"ResponsiveScale","desc":"Keeps the pixel values of tagged ScreenGuis proportional to the screen, so\\na GUI authored at 1920x1080 looks the same on a phone and on a 4K monitor.\\nScale-sized frames resize on their own; these values do not.\\n\\n`f = min(ViewportSize.X / 1920, ViewportSize.Y / 1080)`.\\n- `UITextSizeConstraint`: below 1080p (`f < 1`) Min and Max are both\\n  `AuthoredMax * f`, forcing the exact proportional size. At or above it,\\n  both limits are scaled by `f`. Limits are capped at 100 (engine cap).\\n- `ScrollingFrame.ScrollBarThickness`: scaled by `f`.\\n\\nOpt in by tagging a ScreenGui `ResponsiveScale` in Studio. Author\\n`MaxTextSize` as the size the text has at 1920x1080. Authored values are\\nstored once as `Authored<Property>` attributes, so rescales never compound\\nand runtime clones carry them. `Init` is called once from\\n`ResponsiveScaleController.client.luau`.","realm":["Client"],"source":{"line":22,"path":"src/ReplicatedStorage/SharedModules/Gui/ResponsiveScale.luau"}}')}}]);